function bilibiliEpisodes(lessonId) {
  const list = BILIBILI_EPISODES[Number(lessonId)]
  if (!Array.isArray(list)) return []
  return list.map(([page, label, seconds]) => ({ page, label, seconds }))
}

function bilibiliEmbedUrl(page) {
  const value = Number(page)
  const suffix = Number.isFinite(value) && value > 0 ? `&page=${Math.round(value)}` : ''
  return `https://player.bilibili.com/player.html?bvid=${BILIBILI_SOURCE.bvid}${suffix}&high_quality=1&autoplay=0`
}

function bilibiliPageUrl(page) {
  const value = Number(page)
  const suffix = Number.isFinite(value) && value > 0 ? `?p=${Math.round(value)}` : ''
  return `${BILIBILI_SOURCE.url}${suffix}`
}
